        /// <param name="id">ID de la organización. También puedes usar `me` con la Live Secret Key de la organización.</param>
        /// <param name="cerFile">Format: binary Contenido binario del archivo con extensión `.cer` de la e.firma (FIEL). Usa un Stream; se dispone al finalizar la solicitud.</param>
        /// <param name="keyFile">Format: binary Contenido binario del archivo con extensión `.key` de la e.firma (FIEL). Usa un Stream; se dispone al finalizar la solicitud.</param>
        /// <param name="password">Contraseña de la llave privada de la e.firma (FIEL).</param>
        /// <param name="cancellationToken">Permite cancelar la solicitud.</param>
        /// <returns>Objeto `Organization` modificado</returns>
        /// <see href="https://docs.facturapi.io/api/#operation/uploadOrganizationFiel"/>
        public async Task<Organization> UploadFielAsync(string id, Stream cerFile, Stream keyFile, string password, CancellationToken cancellationToken = default)
        {
            using (var form = new MultipartFormDataContent())
            {
                form.Add(new StreamContent(cerFile), "cer", "cer.cer");
                form.Add(new StreamContent(keyFile), "key", "key.key");
                form.Add(new StringContent(password), "password");
                return await RequestMultipartAsync<Organization>(HttpMethod.Put, $"organizations/{Uri.EscapeDataString(id)}/fiel", form, cancellationToken).ConfigureAwait(false);
            }
        }

    }
}
